  /// 退貨運送中 — 買家已寄出，物流配送中
  returnShipping(code: 'RETURN_SHIPPING', value: '25', label: '退貨運送中'),
  /// 退貨已到店待取 — 超商退貨配達退貨門市，等待賣家領取（72 小時內未取則系統自動完成確認收貨）。僅超商退貨（returnShippingMethod=3002）使用
  returnAtStore(code: 'RETURN_AT_STORE', value: '26', label: '退貨已到店待取'),
  /// 退貨已送達 — 超商退貨：賣家從門市實際取貨完成；宅配退貨：包裹送達賣家地址並簽收。等待賣家確認收貨（48 小時內未確認則系統自動完成）
  returnDelivered(code: 'RETURN_DELIVERED', value: '27', label: '退貨已送達'),
  /// 退貨物流失敗 — 退貨物流發生 PayUni ABNORMAL 狀態（包裹遺失/退回買家等），需 Admin 介入或走申訴流程
  returnFailed(code: 'RETURN_FAILED', value: '28', label: '退貨物流失敗'),
