  returnReceived(code: 'RETURN_RECEIVED', value: '30', label: '已收退貨'),
  /// 超商待取逾時自動完成 — 超商退貨配達門市後賣家逾 72 小時未領取，系統自動推進完成確認收貨並退款。前端可直接以本狀態 label 顯示
  autoCompletedStorePickupTimeout(code: 'AUTO_COMPLETED_STORE_PICKUP_TIMEOUT', value: '31', label: '超商待取逾時自動完成'),
  /// 確認收貨逾時自動完成 — 退貨送達後賣家逾 48 小時未確認收貨，系統自動推進完成確認收貨並退款。前端可直接以本狀態 label 顯示
  autoCompletedConfirmReceiptTimeout(code: 'AUTO_COMPLETED_CONFIRM_RECEIPT_TIMEOUT', value: '32', label: '確認收貨逾時自動完成'),
  /// 待寄回逾時自動關案 — 進入 RETURN_PENDING(20) 後買家逾 ship_back_deadline_at（預設 7 天）未寄回，系統自動關案，退款資格解除，訂單款項照常撥付賣家。本狀態為「不退款」終態（不轉 REFUND_PROCESSING）；買家不服可走 §10 申訴流程，Admin 裁決退款時 status 改回 REFUND_PROCESSING(40)，裁決駁回時轉 CLOSED(50)。前端可直接以本狀態 label 顯示
  autoCompletedReturnPendingTimeout(code: 'AUTO_COMPLETED_RETURN_PENDING_TIMEOUT', value: '33', label: '待寄回逾時自動關案'),
  /// 退款處理中 — 退款任務建立並執行中
  refundProcessing(code: 'REFUND_PROCESSING', value: '40', label: '退款處理中'),
