  /// 參數錯誤 — 400。schema／格式驗證失敗的通用碼（invalid requestId、clientRequestId is required…）
  invalidArgument(code: 'INVALID_ARGUMENT', value: 'INVALID_ARGUMENT', label: '參數錯誤'),
  /// 無權操作 — 403。呼叫端身分無法解析或無權存取此 request
  permissionDenied(code: 'PERMISSION_DENIED', value: 'PERMISSION_DENIED', label: '無權操作'),
  /// 資源不存在 — 404 通用碼。cross-buyer 與亂數 ID 共用同一外形，不洩漏存在性
  resourceNotFound(code: 'RESOURCE_NOT_FOUND', value: 'RESOURCE_NOT_FOUND', label: '資源不存在'),
  /// 系統錯誤 — 500
  internalError(code: 'INTERNAL_ERROR', value: 'INTERNAL_ERROR', label: '系統錯誤'),
  /// 請求過於頻繁 — 429。可重試性由 `Retry-After` header 表達（串流路徑因 header 已 flush，改由 error frame 帶延遲）
  rateLimited(code: 'RATE_LIMITED', value: 'RATE_LIMITED', label: '請求過於頻繁'),
  /// 功能暫不可用 — 503。capability 關閉時的 typed failure，不得靜默降級成舊行為
  capabilityUnavailable(code: 'CAPABILITY_UNAVAILABLE', value: 'CAPABILITY_UNAVAILABLE', label: '功能暫不可用'),
  /// 版本不支援 — 400。client 要求的 major schema 版本不受支援
  schemaVersionUnsupported(code: 'SCHEMA_VERSION_UNSUPPORTED', value: 'SCHEMA_VERSION_UNSUPPORTED', label: '版本不支援'),
  /// 需求不存在 — 404。採購需求不存在或不屬於此買家
  requestNotFound(code: 'REQUEST_NOT_FOUND', value: 'REQUEST_NOT_FOUND', label: '需求不存在'),
  /// 冪等鍵衝突 — 409。同一 clientRequestId 已綁定另一份 payload。**不是** #2446 原文的 IDEMPOTENCY_KEY_REUSED——單純 reuse（同鍵同內容）在本系統是成功的 replay 路徑，用 REUSED 命名等於拿正常路徑的名字命名錯誤
  idempotencyKeyConflict(code: 'IDEMPOTENCY_KEY_CONFLICT', value: 'IDEMPOTENCY_KEY_CONFLICT', label: '冪等鍵衝突'),
  /// 版本已過期 — 409。expectedRevisionId 與現行 revision 不符
  staleRevision(code: 'STALE_REVISION', value: 'STALE_REVISION', label: '版本已過期'),
  /// 需求尚未齊備 — 409。必填欄位未填滿即嘗試進入候選比對
  requirementNotReady(code: 'REQUIREMENT_NOT_READY', value: 'REQUIREMENT_NOT_READY', label: '需求尚未齊備'),
  /// 回答格式不符 — 422。答案不符合該問題卡的 schema（例如複合問題缺 unitOptionId）
  answerSchemaInvalid(code: 'ANSWER_SCHEMA_INVALID', value: 'ANSWER_SCHEMA_INVALID', label: '回答格式不符'),
  /// 此欄位不可略過 — 422。對必填欄位送出 skip
  slotNotSkippable(code: 'SLOT_NOT_SKIPPABLE', value: 'SLOT_NOT_SKIPPABLE', label: '此欄位不可略過'),
  /// 品項選擇無效 — 422。crop-disambiguation 選項不在可選集合內
  cropChoiceInvalid(code: 'CROP_CHOICE_INVALID', value: 'CROP_CHOICE_INVALID', label: '品項選擇無效'),
  /// 輸入過長 — 422。訊息或自由文字超過長度上限
  inputTooLong(code: 'INPUT_TOO_LONG', value: 'INPUT_TOO_LONG', label: '輸入過長'),
  /// 本月 Agent 額度已用完 — 429。本月額度已用盡，回 remaining=0 與 resetAt（下期起始時間）——doc 57 §7
  agentMonthlyQuotaExceeded(code: 'AGENT_MONTHLY_QUOTA_EXCEEDED', value: 'AGENT_MONTHLY_QUOTA_EXCEEDED', label: '本月 Agent 額度已用完'),
  /// 覆寫欄位無效 — 400。報價單邀請的買家覆寫欄位格式或值不合法
  invalidOverride(code: 'INVALID_OVERRIDE', value: 'INVALID_OVERRIDE', label: '覆寫欄位無效'),
  /// 對話標題無效 — 422。改名的標題為空或超長
  conversationTitleInvalid(code: 'CONVERSATION_TITLE_INVALID', value: 'CONVERSATION_TITLE_INVALID', label: '對話標題無效'),
  /// 候選資料已過期 — 409。候選事實的 factsAsOf 已早於現行需求版本，須重新比對
  candidateFactsStale(code: 'CANDIDATE_FACTS_STALE', value: 'CANDIDATE_FACTS_STALE', label: '候選資料已過期'),
  /// 通道不符 — 400。指定的 lane 與候選實際所屬通道不一致
  laneMismatch(code: 'LANE_MISMATCH', value: 'LANE_MISMATCH', label: '通道不符'),
  /// 邀請已被處理 — 409。該報價邀請已被確認或已失效（先到先得）
  inviteAlreadyResolved(code: 'INVITE_ALREADY_RESOLVED', value: 'INVITE_ALREADY_RESOLVED', label: '邀請已被處理'),
  /// 報價基準無法解析 — 422。currency/quantity/unit/conversion basis 無法 canonicalize，RFQ 報價預覽的 typed hard block，零 side effect、不建立 preview 列（issue #2403 Slice 2）
  priceBasisUnavailable(code: 'PRICE_BASIS_UNAVAILABLE', value: 'PRICE_BASIS_UNAVAILABLE', label: '報價基準無法解析'),
  /// Run 非執行中 — 409。對非 QUEUED/RUNNING/WAITING_FOR_INPUT 狀態的 run 送出需要 active run 的命令
  runNotActive(code: 'RUN_NOT_ACTIVE', value: 'RUN_NOT_ACTIVE', label: 'Run 非執行中'),
  /// 中斷已逾期 — 409。resume 命令對應的 interrupt 已超過 expiresAt
  interruptExpired(code: 'INTERRUPT_EXPIRED', value: 'INTERRUPT_EXPIRED', label: '中斷已逾期'),
  /// 核准依據已過期 — 409。resume/確認命令帶的 expectedVersion 與現行版本不符
  approvalStale(code: 'APPROVAL_STALE', value: 'APPROVAL_STALE', label: '核准依據已過期'),
  /// Replay 游標已過期 — 410。GET replay 的 Last-Event-ID 早於 minAvailableSeqId
  replayCursorExpired(code: 'REPLAY_CURSOR_EXPIRED', value: 'REPLAY_CURSOR_EXPIRED', label: 'Replay 游標已過期'),
  /// Replay 游標超前 — 409。GET replay 的 Last-Event-ID 高於目前 high-water mark
  replayCursorAhead(code: 'REPLAY_CURSOR_AHEAD', value: 'REPLAY_CURSOR_AHEAD', label: 'Replay 游標超前'),
  /// 核准已被處理 — 409。對已 resolved 的 interrupt 重複送出 resume/確認命令
  approvalAlreadyResolved(code: 'APPROVAL_ALREADY_RESOLVED', value: 'APPROVAL_ALREADY_RESOLVED', label: '核准已被處理'),
  /// Run 結果尚未就緒 — 422（#3330 起；原為 503 —— 服務端改用 codes.FailedPrecondition，而 procurement 走自己的對照表 gateway/internal/procurement/wire.go，那裡 FailedPrecondition 映 422、409 留給 Aborted）。命令的冪等鍵命中一個已建立的 run，但該 run 沒有可重播的結果。**兩種成因、處置相反，呼叫端不得一律重試**：(1) run 仍在執行中 → 稍後重試**同一把** clientRequestId 可能就緒；(2) run 已以 FAILED 收尾 → 該鍵永遠不會再產生可重播結果，必須改用**新的** clientRequestId 重下命令，重試同一把鍵會無限迴圈。本碼本身不區分兩者（區分需要讀 run 狀態），呼叫端若要自動重試必須設重試上限，或改查 run 狀態再決定。與 `RUN_NOT_ACTIVE` 是兩件事：那個講的是「run 的狀態不允許這個命令」，這個講的是「命令已受理、但沒有結果可回」
  runResultNotReady(code: 'RUN_RESULT_NOT_READY', value: 'RUN_RESULT_NOT_READY', label: 'Run 結果尚未就緒'),
  /// 待回覆的中斷 — 409。該需求有一個尚未回覆的 interrupt（run 停在 WAITING_FOR_INPUT），必須改用 POST /runs/{runId}/resume 回覆；/answers 與 /crop-disambiguation 在此期間不得直接寫入，否則會讓 interrupt 孤兒化
  approvalPending(code: 'APPROVAL_PENDING', value: 'APPROVAL_PENDING', label: '待回覆的中斷'),
  /// 詢價快照已過期 — 409。acceptance 的 expectedRfqSnapshotHash 與現行 confirmed snapshot 不符（需求被其他裝置改過）。零 side effect，不建立任何 acceptance 列（doc 64 §9.2，#2538）
  staleRfqSnapshot(code: 'STALE_RFQ_SNAPSHOT', value: 'STALE_RFQ_SNAPSHOT', label: '詢價快照已過期'),
  /// 發布依據已過期 — 409。賣家回價命令帶的 publication id／version／sellerFacingPayloadHash 與現行不符。零 side effect（doc 64 §9.2，#2538）
  stalePublication(code: 'STALE_PUBLICATION', value: 'STALE_PUBLICATION', label: '發布依據已過期'),
  /// 供應商報價已變動 — 409。expectedSellerResponseVersion 不是目前版本——賣家已改價或已撤回。⛔ **必須明確告知使用者報價已變動，不得靜默改用最新版重試**（doc 64 §9.2，#2538）
  staleSellerResponse(code: 'STALE_SELLER_RESPONSE', value: 'STALE_SELLER_RESPONSE', label: '供應商報價已變動'),
  /// 已提交過正式回價 — 409。賣家帶著「尚無正式回價」的 CAS（空 expectedSellerResponseVersion）提交，但該 publication 上已有一版。改版要帶目前版本（v6.0 Part III §13.1，#2538）
  rfqResponseAlreadySubmitted(code: 'RFQ_RESPONSE_ALREADY_SUBMITTED', value: 'RFQ_RESPONSE_ALREADY_SUBMITTED', label: '已提交過正式回價'),
  /// 報價已逾有效期 — 409。被 shortlist 或被接受的 sellerResponseVersion 已過 validUntil。⛔ 不可接受，也不得自動改接受別版（v6.0 Part III §13.1，#2538）
  rfqResponseExpired(code: 'RFQ_RESPONSE_EXPIRED', value: 'RFQ_RESPONSE_EXPIRED', label: '報價已逾有效期'),
  /// 該收件人已停止寫入 — 409。賣家已明確拒絕（decline），或 publication 已結案／他人成交後停止寫入（v6.0 Part III §13.1，#2538）
  rfqRecipientClosed(code: 'RFQ_RECIPIENT_CLOSED', value: 'RFQ_RECIPIENT_CLOSED', label: '該收件人已停止寫入'),
  /// 已有進行中的成交 — 409。同一 request 已有 ACTIVE 的 acceptance。回既有 orderNo 讓買家去付款，**不是**叫他重新接受（v6.0 Part III §13.1，#2538）
  rfqCheckoutAlreadyActive(code: 'RFQ_CHECKOUT_ALREADY_ACTIVE', value: 'RFQ_CHECKOUT_ALREADY_ACTIVE', label: '已有進行中的成交'),
