  issuing(code: 'ISSUING', value: 'ISSUING', label: '開立中'),
  /// 已開立 — provider 明確成功並回填發票號碼。**靜止態非封閉終態**——仍可作廢、被取代或被折讓
  issued(code: 'ISSUED', value: 'ISSUED', label: '已開立'),
  /// 開立失敗 — operation 進入任一 FAILED_*；ADM 工作台可重試或轉人工
  issueFailed(code: 'ISSUE_FAILED', value: 'ISSUE_FAILED', label: '開立失敗'),
  /// 待人工處理 — 送出前的不變式斷言失敗、決策層 fail-closed、或逾法定期限；`manual_reason_code` 由 `chk_invdoc_manual_reason` 強制非空（理由碼見 InvoiceManualReason **32 值**）
  awaitingManual(code: 'AWAITING_MANUAL', value: 'AWAITING_MANUAL', label: '待人工處理'),
  /// 作廢中 — VOID operation 已進入 SENDING
  voiding(code: 'VOIDING', value: 'VOIDING', label: '作廢中'),
  /// 已作廢 — 作廢確認完成（AMEGO f0501）。折讓單被 g0501 作廢是 `invoice_adjustments` 那條線的事，不落本欄
  voided(code: 'VOIDED', value: 'VOIDED', label: '已作廢'),
  /// 已被重開取代 — 重開出來的新文件已 ISSUED，本件為舊件（終態）
