/// 對 provider 的一次操作（＝排程 job）的執行狀態。六種 `operation_type` 共用同一套值域（58 §7.3.0 規則 1）。**搶佔不用狀態欄**——租約走 `next_attempt_at` 的 CAS（多副本排程搶佔規範），所以 SENDING 就是「正在送」而不是「被誰鎖住」。
enum InvoiceOperationStatus {
  /// 已建立 — 剛落庫，尚未判定可否立即執行（同一事務內即離開）
  created(code: 'CREATED', value: 'CREATED', label: '已建立'),
  /// 等待觸發時點 — `issue_not_before > now`；**不在任何 worker 的候選述詞內**，由 INV.op 的 RunOnce 前置步驟 promote
  awaitingTrigger(code: 'AWAITING_TRIGGER', value: 'AWAITING_TRIGGER', label: '等待觸發時點'),
  /// 待執行 — 可被 claim
  ready(code: 'READY', value: 'READY', label: '待執行'),
  /// 暫停（買家修改中） — 買家送出付款後修改，`held_until = now + 60s`
  held(code: 'HELD', value: 'HELD', label: '暫停（買家修改中）'),
  /// 送出中 — 已 claim，租約 120 秒；租約過期即自動回收
  sending(code: 'SENDING', value: 'SENDING', label: '送出中'),
  /// 等待重試 — 可重試錯誤，`next_attempt_at = now + 2^attempt × 30s`
  retryScheduled(code: 'RETRY_SCHEDULED', value: 'RETRY_SCHEDULED', label: '等待重試'),
  /// 等待結果確認 — 逾時／結果不確定，落在 INV.rc 的候選集合
  waitingConfirmation(code: 'WAITING_CONFIRMATION', value: 'WAITING_CONFIRMATION', label: '等待結果確認'),
  /// 重查中 — INV.rc 已 claim，租約 60 秒
  providerStatusRecheck(code: 'PROVIDER_STATUS_RECHECK', value: 'PROVIDER_STATUS_RECHECK', label: '重查中'),
  /// 已完成 — provider 明確成功（終態）
  succeeded(code: 'SUCCEEDED', value: 'SUCCEEDED', label: '已完成'),
  /// 永久失敗 — 重試必然再失敗（統編錯／金額不平／字軌不足）；ADM 需先修正資料才可重試
  failedPermanent(code: 'FAILED_PERMANENT', value: 'FAILED_PERMANENT', label: '永久失敗'),
  /// 重試次數用盡 — 暫時性錯誤但預算用完；**ADM 直接重試是安全的**
  failedRetryExhausted(code: 'FAILED_RETRY_EXHAUSTED', value: 'FAILED_RETRY_EXHAUSTED', label: '重試次數用盡'),
  /// 結果未確認 — 重試可能開出第二張發票；唯一出邊是重查
  failedUnknown(code: 'FAILED_UNKNOWN', value: 'FAILED_UNKNOWN', label: '結果未確認'),
  /// 待賣家處理 — 永久失敗，**但賣家自己解得掉**（AMEGO `3040111` 字軌不足 ⇒ 賣家須向財政部申請丁種字軌）。不在任何 worker 的候選述詞內，由 INV.trk 的 RunOnce 前置步驟在字軌恢復時 promote 回 READY
  sellerActionRequired(code: 'SELLER_ACTION_REQUIRED', value: 'SELLER_ACTION_REQUIRED', label: '待賣家處理'),
  /// 取消申請中 — ADM 已提出取消，等強制最終查詢
  cancelRequested(code: 'CANCEL_REQUESTED', value: 'CANCEL_REQUESTED', label: '取消申請中'),
  /// 取消被擋（結果未明） — 仍無法確認 provider 端是否已開立，拒絕取消
  cancelBlockedUnknown(code: 'CANCEL_BLOCKED_UNKNOWN', value: 'CANCEL_BLOCKED_UNKNOWN', label: '取消被擋（結果未明）'),
  /// 已由管理員取消 — 雙人確認 ＋ 證據齊備
  cancelledByAdmin(code: 'CANCELLED_BY_ADMIN', value: 'CANCELLED_BY_ADMIN', label: '已由管理員取消'),
  /// 已解鎖人工處理 — 第二人覆核解鎖，賣家可自行開立並回報
  manualProcessAllowed(code: 'MANUAL_PROCESS_ALLOWED', value: 'MANUAL_PROCESS_ALLOWED', label: '已解鎖人工處理'),
  /// 賣家自行開立並回報 — 賣家回報號碼（終態）
  resolvedExternally(code: 'RESOLVED_EXTERNALLY', value: 'RESOLVED_EXTERNALLY', label: '賣家自行開立並回報'),
  /// 不適用 — 決策樹判定不由平台開立（終態）
  notApplicable(code: 'NOT_APPLICABLE', value: 'NOT_APPLICABLE', label: '不適用'),
  /// 開立前已取消 — 開立前全額退款（終態）
  cancelledBeforeIssue(code: 'CANCELLED_BEFORE_ISSUE', value: 'CANCELLED_BEFORE_ISSUE', label: '開立前已取消');

  const InvoiceOperationStatus({
