  /// 審核中 — 賣家已宣稱、平台尚未認可；**不出現在公開投影**。同一 `(product, type)` 最多一筆（partial unique `uk_pca_pending`）
  submitted(code: 'SUBMITTED', value: 'SUBMITTED', label: '審核中'),
  /// 已通過 — 平台已認可，**出現在公開投影**；投影重算的唯一輸入集合。同一 `(product, type)` 最多一筆（partial unique `uk_pca_active`）
  approved(code: 'APPROVED', value: 'APPROVED', label: '已通過'),
  /// 未通過 — ADM 判定不成立（終態）。`reason_code` 必填；重送同一組號碼會帶 `requires_manual_review=true`，不得因政府查驗剛好通過就繞過裁決
  rejected(code: 'REJECTED', value: 'REJECTED', label: '未通過'),
  /// 已撤回 — 賣家停止宣稱（終態）：專用 withdraw 端點、該 type 在全量取代中完全沒送、或**商品被軟刪**（#2820，連帶撤回該商品全部 `SUBMITTED`；此路徑的事件 `actor_role=SYSTEM`，見 `業務類型碼.md` 的 `ProductCertificationReviewAction.WITHDRAW`）
  withdrawn(code: 'WITHDRAWN', value: 'WITHDRAWN', label: '已撤回'),
  /// 已被新號碼取代 — 被同 type 的新號碼取代（終態）。由系統在核准新號碼的第一步寫入，保留換號歷程
  superseded(code: 'SUPERSEDED', value: 'SUPERSEDED', label: '已被新號碼取代'),
  /// 已撤銷 — ADM 事後撤銷已公開的標章（終態），`reason_code` 必填。**唯一的治理手段**——政府 API 只驗「號碼存在」不驗「歸屬」，盜用他人證號會自動通過查驗
  revoked(code: 'REVOKED', value: 'REVOKED', label: '已撤銷');

