  /// 訂單建立中 — 已接受、價格已凍結、**尚未付款**；`orderNo` 與 `paymentDeadline` 為空字串
  creatingOrder(code: 'CREATING_ORDER', value: 'CREATING_ORDER', label: '訂單建立中'),
  /// 訂單已建立 — order shell 已建；`orderNo` 與 `paymentDeadline` 此時才有值
  orderCreated(code: 'ORDER_CREATED', value: 'ORDER_CREATED', label: '訂單已建立'),
  /// 建單失敗 — 需要前滾或補償；acceptance 本身仍成立
  orderFailed(code: 'ORDER_FAILED', value: 'ORDER_FAILED', label: '建單失敗');

  const ProcurementOrderProvisioningState({
    required this.code,
    required this.value,
    required this.label,
  });

  final String code;
  final String value;
  final String label;

  /// 依 code 查找，找不到回傳 null
  static ProcurementOrderProvisioningState? fromCode(String code) {
    for (final v in values) {
      if (v.code == code) return v;
    }
    return null;
  }

  /// 依 value 查找，找不到回傳 null
  static ProcurementOrderProvisioningState? fromValue(String value) {
    for (final v in values) {
      if (v.value == value) return v;
    }
    return null;
  }
}

