/// 配送異常類型。由 shipping-service 之既有 scheduler 與 webhook consumer 偵測 shipments / seller_shipment_settings 既有狀態欄位（status / tcat_call_status / label_print_status / payuni_submit_status）異常時發布 `shipment.anomaly.detected` event 用。**異常本身的狀態仍以 shipments 既有欄位為唯一真實來源**，本 enum 僅標示「賣家收到通知時看到的異常分類」。詳見 [06 §5.21](../詳細設計書/06-物流微服務（Shipping%20Service）詳細設計書.md#521-配送異常賣家通知)。
enum ShipmentAnomalyType {
  /// 黑貓叫件未完成 — 賣家呼叫黑貓後 24h 內 tcat_call_status 仍為 REQUESTED（4202）
  tcatCallFailed(code: 'TCAT_CALL_FAILED', value: 'TCAT_CALL_FAILED', label: '黑貓叫件未完成'),
  /// 超商標籤未列印 — 賣家列印超商標籤後 48h 仍未交件（label_print_status 卡 4102）
  cvsLabelUnprinted(code: 'CVS_LABEL_UNPRINTED', value: 'CVS_LABEL_UNPRINTED', label: '超商標籤未列印'),
  /// 物流商回報異常 — shipments.status=33（異常）。41 CANCELLED 為賣家自取消（不算物流商異常），44 走 PACKAGE_LOST
  providerStatusAbnormal(code: 'PROVIDER_STATUS_ABNORMAL', value: 'PROVIDER_STATUS_ABNORMAL', label: '物流商回報異常'),
  /// 包裹遺失（卡待取貨） — shipments.status 卡 32 待取貨超過 7 天
  packageLost(code: 'PACKAGE_LOST', value: 'PACKAGE_LOST', label: '包裹遺失（卡待取貨）'),
  /// 配送逾期 — 超過 expected_delivery_date 且物流商超過 3 天無狀態更新（軌跡近期仍活躍視為仍在正常移動，不打異常）
  deliveryOverdue(code: 'DELIVERY_OVERDUE', value: 'DELIVERY_OVERDUE', label: '配送逾期'),
  /// PayUni 回 SUCCESS 但無三段碼 — PayUni 列印 Webhook SUCCESS 但 partnerId / odno / validationNo 為空（B-143 重現）
  payuniLgsNoCode(code: 'PAYUNI_LGS_NO_CODE', value: 'PAYUNI_LGS_NO_CODE', label: 'PayUni 回 SUCCESS 但無三段碼'),
  /// 退貨流程卡住 — aftersale_case 退貨流程超過 14 天無狀態進展
  returnStuck(code: 'RETURN_STUCK', value: 'RETURN_STUCK', label: '退貨流程卡住'),
  /// Uber 外送員未指派 — 建單成功後停在 UNPROCESSED(91) 超過 30 分鐘仍未指派外送員（66 §5.1.11）
  uberCourierUnassigned(code: 'UBER_COURIER_UNASSIGNED', value: 'UBER_COURIER_UNASSIGNED', label: 'Uber 外送員未指派'),
  /// Uber 取件停滯 — 停在 COURIER_ASSIGNED(933) 超過 45 分鐘仍未取件（66 §5.1.11）
  uberPickupStuck(code: 'UBER_PICKUP_STUCK', value: 'UBER_PICKUP_STUCK', label: 'Uber 取件停滯'),
  /// Uber 建單結果未知且未收斂 — CREATE_UNKNOWN(991) 超過回查窗仍未知（66 §5.1.11）
  uberCreateUnknownUnresolved(code: 'UBER_CREATE_UNKNOWN_UNRESOLVED', value: 'UBER_CREATE_UNKNOWN_UNRESOLVED', label: 'Uber 建單結果未知且未收斂'),
  /// Uber 送達憑證缺漏 — delivered 後 7 天內未取得任何 POD（66 §5.1.11／INV-U5）
  uberPodMissing(code: 'UBER_POD_MISSING', value: 'UBER_POD_MISSING', label: 'Uber 送達憑證缺漏');

