  sellerQuoteResult(code: 'SELLER_QUOTE_RESULT', value: 'SELLER_QUOTE_RESULT', label: '賣家報價結果'),
  /// 錯誤復原引導 — Track A。承載 `ProcurementErrorReason`／`ProcurementRunFailureReason` 的公開復原建議，`data` 形狀已可從既有錯誤碼登記推導
  errorRecovery(code: 'ERROR_RECOVERY', value: 'ERROR_RECOVERY', label: '錯誤復原引導'),
