/// 對政府開放資料平台查驗該證書編號的結果狀態。⚠️ 本值域是**查驗結果**，與審核狀態 `ProductCertificationStatus` 是兩件事：`VERIFIED` 不等於 `APPROVED`（3703 CAS 查得到只證明該工廠有資格、不證明這個商品是 CAS 產品，一律人工審），`NOT_FOUND` 也不等於 `REJECTED`（證書可能在申請之後才登記上政府資料庫，ADM 可按「重新查驗」）。⚠️ 也**不要**與 `ProductCertificationValidity` 合併：那張表是「政府資料判讀出的證書效力」（含 `TERMINATED` 已終止／`SUSPENDED` 暫時終止），本值域是「我方查驗流程走到哪」（含 `PENDING`／`UNSUPPORTED`／`UNAVAILABLE` 這三個與證書效力無關的流程態）；本值域的 `EXPIRED` 是那三個失效值**塌縮後**的結果，有損，ADM 要判斷處置一律讀 `govVerifyPayload.validity`。🔴 **`UNAVAILABLE` 與 `NOT_FOUND` 絕不可合併**：政府 API 金鑰失效時回 `{"RS":"ERROR"}` 且 HTTP 200 無 `Data` 欄，舊實作把它判成「查無此證書」⇒ 金鑰一出事全站所有編號都被判為假的且無任何錯誤訊號（19 §8.4 防線 1 實測）。
enum ProductCertificationGovVerifyState {
  /// 待查驗 — DB 預設值；背景查驗事件尚未處理完成
  pending(code: 'PENDING', value: 'PENDING', label: '待查驗'),
  /// 查驗通過 — 政府資料查得到且推導出的 `validity = VALID`。⚠️ 只有 3701 有機（有權威 `Status` 欄＋效期＋編號一對一）會據此自動核准
  verified(code: 'VERIFIED', value: 'VERIFIED', label: '查驗通過'),
  /// 查無此編號 — 政府資料查無此編號。**不是**上游故障——上游故障一律落 `UNAVAILABLE`
  notFound(code: 'NOT_FOUND', value: 'NOT_FOUND', label: '查無此編號'),
  /// 證書已失效 — 查得到但推導出 `EXPIRED`／`TERMINATED`／`SUSPENDED`；需人工審
  expired(code: 'EXPIRED', value: 'EXPIRED', label: '證書已失效'),
  /// 不支援線上查驗 — 3704 HACCP／3705 ISO／3706 GMP 無政府開放資料介面，永遠人工審，不排背景查驗
  unsupported(code: 'UNSUPPORTED', value: 'UNSUPPORTED', label: '不支援線上查驗'),
  /// 查驗服務不可用 — 政府 API 逾時／連線失敗／回應的 `RS` 欄不是 OK／編號自我校驗失敗／斷路器命中。ADM 可稍後按「重新查驗」重試
  unavailable(code: 'UNAVAILABLE', value: 'UNAVAILABLE', label: '查驗服務不可用');

  const ProductCertificationGovVerifyState({
    required this.code,
    required this.value,
    required this.label,
  });

  final String code;
  final String value;
  final String label;

  /// 依 code 查找，找不到回傳 null
  static ProductCertificationGovVerifyState? fromCode(String code) {
    for (final v in values) {
      if (v.code == code) return v;
    }
    return null;
  }

  /// 依 value 查找，找不到回傳 null
  static ProductCertificationGovVerifyState? fromValue(String value) {
    for (final v in values) {
      if (v.value == value) return v;
    }
    return null;
  }
}

/// ADM 駁回（`REJECTED`）或撤銷（`REVOKED`）認證申請時必填的結構化原因碼，兩個動作共用同一值域。⚠️ 與 `public_reason` 是兩件事：本值域是**可篩選、可統計、前端可自行翻譯**的碼，`public_reason` 是 ADM 自由填寫、直接展示給賣家的補充說明；只有後者不足以做治理分析，只有前者則說不清個案。缺 `reason_code` 時回 `3028 CERT_REVIEW_REASON_REQUIRED`。
