  certExpired(code: 'CERT_EXPIRED', value: 'CERT_EXPIRED', label: '證書已失效'),
  /// 證書與商品不符 — 證書涵蓋的品項不含本商品。3703 CAS 的典型情境：`Emblem_ID` 是工廠標誌編號，查得到只證明該工廠有 CAS 資格
  certProductMismatch(code: 'CERT_PRODUCT_MISMATCH', value: 'CERT_PRODUCT_MISMATCH', label: '證書與商品不符'),
