/// 系統決定「這一筆不自己處理、轉人工」時的理由碼。**三個來源**：① 送出前的不變式斷言失敗（開立側 A1–A15／A20–A23、折讓側 A16–A19）② 決策層的 fail-closed（平台出資券、混合稅別、期限已過等）③ **58 §6.3 P7 `invoice.operation.review_required` 的 `review_reason_code`**（2026-08-25 新增末三值，共用同一值域、**不另開新 enum**，裁決見 58 §6.3.3.3）。**每個碼 <= 32 字元**（欄位寬度），新增前先數字元。
enum InvoiceManualReason {
  /// 服務商結果未確認 — 逾時／連線中斷且重查仍未明；受控人工出口的入口條件
  providerResultUnknown(code: 'PROVIDER_RESULT_UNKNOWN', value: 'PROVIDER_RESULT_UNKNOWN', label: '服務商結果未確認'),
  /// 折扣資金來源待判定 — A22：偵測到 created_by=ADMIN 的券或判不出資金來源；fail-closed，不得靜默以折扣後金額開票
  platformFundedDiscount(code: 'PLATFORM_FUNDED_DISCOUNT', value: 'PLATFORM_FUNDED_DISCOUNT', label: '折扣資金來源待判定'),
  /// 混合稅別待人工判定 — 一張文件含多種稅別而無法自動推導表頭 TaxType
  mixedTaxCategory(code: 'MIXED_TAX_CATEGORY', value: 'MIXED_TAX_CATEGORY', label: '混合稅別待人工判定'),
  /// 合併訂單待人工處理 — 一筆付款對應多張訂單，開票拆分規則未定
  consolidatedOrder(code: 'CONSOLIDATED_ORDER', value: 'CONSOLIDATED_ORDER', label: '合併訂單待人工處理'),
  /// 開票主體已停止營運 — issuer 已 retired，無有效稅籍可用
  issuerRetired(code: 'ISSUER_RETIRED', value: 'ISSUER_RETIRED', label: '開票主體已停止營運'),
  /// 已逾法定存證期限 — 由 idx_invdoc_deadline 的逾期掃描寫入
  deadlineMissed(code: 'DEADLINE_MISSED', value: 'DEADLINE_MISSED', label: '已逾法定存證期限'),
  /// 明細加總與訂單金額不符 — A1
  amountMismatch(code: 'AMOUNT_MISMATCH', value: 'AMOUNT_MISMATCH', label: '明細加總與訂單金額不符'),
  /// 稅額拆解不平 — A2：Sales + Free + Zero + Tax != Total
  taxSplitMismatch(code: 'TAX_SPLIT_MISMATCH', value: 'TAX_SPLIT_MISMATCH', label: '稅額拆解不平'),
  /// 表頭金額為負 — A3
  negativeHeaderAmount(code: 'NEGATIVE_HEADER_AMOUNT', value: 'NEGATIVE_HEADER_AMOUNT', label: '表頭金額為負'),
  /// 稅別桶加總為負 — A4
  negativeBucket(code: 'NEGATIVE_BUCKET', value: 'NEGATIVE_BUCKET', label: '稅別桶加總為負'),
  /// 品項行正負號錯誤 — A5：DISCOUNT 行必須為負、其餘必須非負
  lineSignInvalid(code: 'LINE_SIGN_INVALID', value: 'LINE_SIGN_INVALID', label: '品項行正負號錯誤'),
  /// 輸出了零元品項行 — A6
  zeroLineEmitted(code: 'ZERO_LINE_EMITTED', value: 'ZERO_LINE_EMITTED', label: '輸出了零元品項行'),
  /// 二聯式稅額非零 — A7
