  /// 三聯式稅額計算錯誤 — A8
  b2bTaxMiscalc(code: 'B2B_TAX_MISCALC', value: 'B2B_TAX_MISCALC', label: '三聯式稅額計算錯誤'),
  /// 表頭稅別與明細不符 — A9
  headerTaxtypeMismatch(code: 'HEADER_TAXTYPE_MISMATCH', value: 'HEADER_TAXTYPE_MISMATCH', label: '表頭稅別與明細不符'),
  /// 零稅率尚未支援 — A10：AMEGO 另需 CustomsClearanceMark／ZeroTaxRateReason
  zeroRateNotSupported(code: 'ZERO_RATE_NOT_SUPPORTED', value: 'ZERO_RATE_NOT_SUPPORTED', label: '零稅率尚未支援'),
  /// 三聯式混合稅別未查證 — A11：fail-closed
  b2bMixedTaxUnverified(code: 'B2B_MIXED_TAX_UNVERIFIED', value: 'B2B_MIXED_TAX_UNVERIFIED', label: '三聯式混合稅別未查證'),
  /// 品項行數超出範圍 — A12：1 <= n <= 9999
  lineCountInvalid(code: 'LINE_COUNT_INVALID', value: 'LINE_COUNT_INVALID', label: '品項行數超出範圍'),
