  /// 折讓稅額拆解不符退款金額 — A16
  allowanceSplitMismatch(code: 'ALLOWANCE_SPLIT_MISMATCH', value: 'ALLOWANCE_SPLIT_MISMATCH', label: '折讓稅額拆解不符退款金額'),
  /// 累計折讓超過原發票金額 — A17：上游允許超額退款，對帳責任在發票端
  allowanceExceedsInvoice(code: 'ALLOWANCE_EXCEEDS_INVOICE', value: 'ALLOWANCE_EXCEEDS_INVOICE', label: '累計折讓超過原發票金額'),
  /// 全額折讓稅額與原發票不符 — A18
  allowanceTaxMismatch(code: 'ALLOWANCE_TAX_MISMATCH', value: 'ALLOWANCE_TAX_MISMATCH', label: '全額折讓稅額與原發票不符'),
