  /// 可折讓基數與總額不符 — A23
  allowanceBaseMismatch(code: 'ALLOWANCE_BASE_MISMATCH', value: 'ALLOWANCE_BASE_MISMATCH', label: '可折讓基數與總額不符'),
  /// 常用發票資料不屬於本訂單買家 — 解析 buyer_invoice_preference_id 時歸屬驗證失敗；**必須拒絕開票，不得 fallback 成無載具**（會把 IDOR 靜默吞掉）
  preferenceOwnershipMismatch(code: 'PREFERENCE_OWNERSHIP_MISMATCH', value: 'PREFERENCE_OWNERSHIP_MISMATCH', label: '常用發票資料不屬於本訂單買家'),
