  voidWindowExpired(code: 'VOID_WINDOW_EXPIRED', value: 'VOID_WINDOW_EXPIRED', label: '作廢等待逾限，改走折讓'),
  /// 法定存證期限逼近 — 58 §7.5.6 的 T−6h 階梯；與既有的 DEADLINE_MISSED（T+0 已逾期）是兩個時點，不可合併
  deadlineApproaching(code: 'DEADLINE_APPROACHING', value: 'DEADLINE_APPROACHING', label: '法定存證期限逼近'),
