  retryBudgetExhausted(code: 'RETRY_BUDGET_EXHAUSTED', value: 'RETRY_BUDGET_EXHAUSTED', label: '重試次數已用盡'),
  /// 賣家字軌不足 — 58 #3082 第二階段：AMEGO 3040111 那一類 —— **要賣家去財政部配字軌**，不是我方改資料、也不是等 provider 恢復。行動指引與其他 provider 失敗完全相反，所以不共用碼（J32 → SELLER_ACTION_REQUIRED 的落點）
  sellerTrackInsufficient(code: 'SELLER_TRACK_INSUFFICIENT', value: 'SELLER_TRACK_INSUFFICIENT', label: '賣家字軌不足'),
