/// 申訴案件時間軸的事件種類（**7 值**）。⚠️ **不是 MQ 事件**（MQ 事件在 InvoiceEventType），是 append-only 時間軸表的分類欄；S09／A07 兩份 UI 分頁都從這張表投影，不各自維護狀態。⚠️ **`REOPENED` 在這裡是「事件」不是「狀態」**——`InvoiceComplaintStatus` 已依 58 §7.3.5 刪除 `REOPENED` 狀態（理由：它與 `OPEN` 行為完全相同），但「買家重開過」這件事必須在時間軸上留痕，`invoice_complaints.reopen_count`（上限 2）配這一列事件即為其載體。
enum InvoiceComplaintEventType {
  /// 買家提出申訴 — actor_type = BUYER
  created(code: 'CREATED', value: 'CREATED', label: '買家提出申訴'),
  /// 賣家回覆 — actor_type = SELLER；action 細分見下方註
  sellerReply(code: 'SELLER_REPLY', value: 'SELLER_REPLY', label: '賣家回覆'),
  /// 升級平台處理 — actor_type = SELLER（請求協助，K03）／BUYER（不接受回覆）／SYSTEM（逾期 24 小時自動升級，K05）。**對應狀態 `ESCALATED_TO_ADM`**
  escalated(code: 'ESCALATED', value: 'ESCALATED', label: '升級平台處理'),
  /// 平台判定 — actor_type = ADMIN；必填理由
  platformDecision(code: 'PLATFORM_DECISION', value: 'PLATFORM_DECISION', label: '平台判定'),
  /// 買家重開案件 — actor_type = BUYER；reopen_count 上限 2
  reopened(code: 'REOPENED', value: 'REOPENED', label: '買家重開案件'),
  /// 買家撤回 — actor_type = BUYER
  withdrawn(code: 'WITHDRAWN', value: 'WITHDRAWN', label: '買家撤回'),
  /// 逾 3 工作天未回覆 — actor_type = SYSTEM；由排程寫入，只發生一次
  slaOverdue(code: 'SLA_OVERDUE', value: 'SLA_OVERDUE', label: '逾 3 工作天未回覆');

