    for (final v in values) {
      if (v.value == value) return v;
    }
    return null;
  }
}

/// 申訴時間軸上「誰選了哪個動作」。⚠️ **與 `InvoiceComplaintEventType` 是同一張表的兩個正交欄位、不是二選一**：`event_type` 答「發生了什麼」（含系統自動事件），`action` 答「賣家或 ADM 在畫面上點了哪一顆」。沒有人做選擇的列（買家提申訴、SLA 逾期、逾時自動升級、**買家不接受（端點 63）**、買家撤回、買家重開）`action` 為 NULL——**買家的動作一律不進本軸**，本 enum 只裝賣家與 ADM 在畫面上點的按鈕。⚠️ ADM 端點 60 的另外兩個 action（`REQUEST_REWORK`／`RECOMMEND_SUSPENSION`）**刻意不寫時間軸**——前者副作用只有重置 SLA，後者只寫建議與稽核（`invoice_admin_audit_logs`），所以本表是 6 值不是 8 值。
enum InvoiceComplaintAction {
  /// 已重新寄送 — actor = SELLER；端點 36。原發票存在，賣家重寄通知／載具
  resent(code: 'RESENT', value: 'RESENT', label: '已重新寄送'),
  /// 已補開或更正 — actor = SELLER；端點 36
  reissued(code: 'REISSUED', value: 'REISSUED', label: '已補開或更正'),
  /// 需要平台協助 — actor = SELLER；端點 36。必填說明，同時把案件推進 `ESCALATED_TO_ADM`（58 §7 K03）
  needPlatformHelp(code: 'NEED_PLATFORM_HELP', value: 'NEED_PLATFORM_HELP', label: '需要平台協助'),
  /// 平台已提醒賣家 — actor = ADMIN；端點 60 的 `REMIND_SELLER`。不改變狀態也不改變 SLA
  reminded(code: 'REMINDED', value: 'REMINDED', label: '平台已提醒賣家'),
  /// 平台判定已解決 — actor = ADMIN；端點 60 的 `DECIDE_RESOLVED`（58 §7 K08）
  decidedResolved(code: 'DECIDED_RESOLVED', value: 'DECIDED_RESOLVED', label: '平台判定已解決'),
  /// 平台判定賣家違規 — actor = ADMIN；端點 60 的 `DECIDE_VIOLATION`（58 §7 K09）。**只有這個值計入 90 天違規計數**
  decidedViolation(code: 'DECIDED_VIOLATION', value: 'DECIDED_VIOLATION', label: '平台判定賣家違規');

  const InvoiceComplaintAction({
    required this.code,
    required this.value,
    required this.label,
  });

  final String code;
  final String value;
  final String label;

  /// 依 code 查找，找不到回傳 null
  static InvoiceComplaintAction? fromCode(String code) {
    for (final v in values) {
      if (v.code == code) return v;
    }
    return null;
  }

  /// 依 value 查找，找不到回傳 null
  static InvoiceComplaintAction? fromValue(String value) {
    for (final v in values) {
      if (v.value == value) return v;
    }
    return null;
  }
}

/// 一張稅務文件的**買家可見歷程**事件。🔴 **它不是 `InvoiceEventType`**——那是 MQ 事件型別（12 值、全部 `INVOICE_` 開頭、前端可見 No、不進任何 allowlist），兩者**交集為空**；把本欄的值拿去查 `InvoiceEventType` 的表只會查不到而顯示空白（`codeLabel` 查不到不報錯）。本值域是 `invoice_status_history` 的**投影**：後端組 `timeline[]` 時把三個 `subject_type` 的狀態轉移摺疊成買家看得懂的五件事，一個轉移最多產生一列。⚠️ 五值刻意**不含失敗與處理中**（`ISSUING`／`ISSUE_FAILED`／`AWAITING_MANUAL` 等內部階段）——買家端對這些的呈現由 `state` ＋ `stateNotice` 承擔（58 §6.1.3），時間軸只記「已經成立的法定事實」。
enum InvoiceDocumentTimelineEvent {
  /// 已開立 — 投影自 `subject_type='DOCUMENT'` 且 `to_status='ISSUED'`（58 §7.3.1）
  issued(code: 'ISSUED', value: 'ISSUED', label: '已開立'),
  /// 已修改 — 投影自 `subject_type='CORRECTION_REQUEST'` 且 `to_status='UPDATED_BEFORE_ISSUE'`（58 §7.3.6 **R03**，開票前改快照）
  updated(code: 'UPDATED', value: 'UPDATED', label: '已修改'),
  /// 已作廢 — 投影自 `subject_type='DOCUMENT'` 且 `to_status='VOIDED'`（58 §7.3.1；該轉態由 §7.3.7 **G09** 的作廢副作用寫入）
  voided(code: 'VOIDED', value: 'VOIDED', label: '已作廢'),
  /// 已重新開立 — 投影自 `subject_type='DOCUMENT'` 且 `to_status='SUPERSEDED'`（58 §7.3.1「重開文件轉 `ISSUED`」那一列）。⚠️ 這一列落在**舊文件**的時間軸上；新文件的時間軸只有它自己的 `ISSUED`
  reissued(code: 'REISSUED', value: 'REISSUED', label: '已重新開立'),
  /// 已開立折讓 — 投影自 `subject_type='ADJUSTMENT'` 且 `to_status='COMPLETED'`，並要求該 `invoice_adjustments.adjustment_type='ALLOWANCE'` 且 `document_id` ＝本文件（58 §7.3.7 **G09**／**G13**／**G17**）
  allowanceApplied(code: 'ALLOWANCE_APPLIED', value: 'ALLOWANCE_APPLIED', label: '已開立折讓');

  const InvoiceDocumentTimelineEvent({
    required this.code,
    required this.value,
    required this.label,
  });

  final String code;
  final String value;
  final String label;

  /// 依 code 查找，找不到回傳 null
  static InvoiceDocumentTimelineEvent? fromCode(String code) {
    for (final v in values) {
      if (v.code == code) return v;
    }
    return null;
  }

  /// 依 value 查找，找不到回傳 null
  static InvoiceDocumentTimelineEvent? fromValue(String value) {
    for (final v in values) {
      if (v.value == value) return v;
    }
    return null;
  }
}

